const ICON_B64 = "";

function iconBytes() {
  const bin = atob(ICON_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}


const OFFICE_ICON_B64 = "";

function officeIconBytes() {
  const bin = atob(OFFICE_ICON_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/apple-touch-icon.png" || url.pathname === "/apple-touch-icon-precomposed.png" || url.pathname === "/icon.png") {
      return new Response(iconBytes(), {
        headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" }
      });
    }
    if (request.method === "POST" && url.pathname === "/update") {
      if (request.headers.get("x-publish-key") !== env.PUBLISH_KEY) {
        return new Response("forbidden", { status: 403 });
      }
      await env.PAGE_KV.put("page", await request.text());
      return new Response("updated");
    }
    if (request.method === "POST" && url.pathname === "/update-share") {
      if (request.headers.get("x-publish-key") !== env.PUBLISH_KEY) {
        return new Response("forbidden", { status: 403 });
      }
      await env.PAGE_KV.put("share", await request.text());
      return new Response("updated");
    }
    if (url.pathname === "/office-icon.png" || url.pathname === "/office-icon-coa.png") {
      return new Response(officeIconBytes(), {
        headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" }
      });
    }
    if (request.method === "POST" && url.pathname === "/update-office") {
      if (request.headers.get("x-publish-key") !== env.PUBLISH_KEY) {
        return new Response("forbidden", { status: 403 });
      }
      await env.PAGE_KV.put("office", await request.text());
      return new Response("updated");
    }
    if (url.pathname === "/office") {
      const officeHtml = await env.PAGE_KV.get("office");
      return new Response(officeHtml || "The Front Office - publishing soon.", {
        headers: { "content-type": "text/html; charset=utf-8" }
      });
    }
    if (url.pathname === "/share") {
      const shareHtml = await env.PAGE_KV.get("share");
      return new Response(shareHtml || "The Daily Scout - share edition publishing soon.", {
        headers: { "content-type": "text/html; charset=utf-8" }
      });
    }
    const html = await env.PAGE_KV.get("page");
    return new Response(html || "The Daily Scout - first edition publishing soon.", {
      headers: { "content-type": "text/html; charset=utf-8" }
    });
  }
};
